command:
set -euo pipefail
echo HOST=$(hostname)
echo LIVE_SHA=$(sha256sum /home/ai-core-node/.claude/star/visual/buehne.html | awk '{print $1}')
echo AVATAR_SERVICE=$(systemctl --user is-active frankenstein-buehne.service || true)
echo BODY_SERVICE=$(systemctl --user is-active frankenstein-koerperpflege.service || true)
echo BODY_RECENT_BEGIN
journalctl --user -u frankenstein-koerperpflege.service --since '-150 seconds' --no-pager -o cat 2>/dev/null | tail -n 30 || true
echo BODY_RECENT_END
echo LOAD=$(cat /proc/loadavg)
echo MEM_AVAILABLE_KB=$(awk '/MemAvailable:/{print $2}' /proc/meminfo)
echo PROD_CHROME_COUNT=$(pgrep -a -f '/opt/google/chrome/chrome --app=http://127.0.0.1:8788/' | grep -v -- '--type=' | grep -v 'bash -lc' | wc -l)
echo HTTP_STATUS=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:8788/ || true)
echo FRESH_ADMISSION_READBACK=PASS
